const TIME_ZONE = 'Europe/Lisbon';
const ESPERA_POST_CITA_MIN = 60;
const DURACIONES_TRATAMIENTO = [
  { patrones: ['revision', 'revision dental'], minutos: 30 },
  { patrones: ['limpieza'], minutos: 60 },
  { patrones: ['blanqueamiento'], minutos: 90 },
  { patrones: ['empaste'], minutos: 45 },
  { patrones: ['ortodoncia'], minutos: 60 }
];

const normalizarTexto = texto => (texto || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const duracionTratamiento = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  const encontrado = DURACIONES_TRATAMIENTO.find(item => item.patrones.some(patron => valor.includes(normalizarTexto(patron))));
  return encontrado ? encontrado.minutos : 60;
};

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    const totalMin = h >= 0 && h < 1 ? Math.round(h * 24 * 60) : Math.round(Math.floor(h) * 60 + (h % 1) * 60);
    return Math.floor(totalMin / 60).toString().padStart(2, '0') + ':' + (totalMin % 60).toString().padStart(2, '0');
  }
  let v = h.toString().trim().toLowerCase().replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').replace('.', ':').trim();
  if (/^\d{1,2}$/.test(v)) return v.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{2}:\d{2}$/.test(v)) v = v.slice(0, 5);
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }
  return v;
};

const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const es = v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (es) return es[3] + '-' + es[2] + '-' + es[1];
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + '-' + iso[2] + '-' + iso[3];
  return v;
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: TIME_ZONE, hour: '2-digit', minute: '2-digit', timeZoneName: 'longOffset' }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const finCita = row => {
  const fecha = normFecha(row.fecha || '');
  const hora = normHora(row.hora || '');
  if (!fecha || !hora) return null;
  const inicio = new Date(fecha + 'T' + hora + ':00' + offsetClinica(fecha, hora));
  if (Number.isNaN(inicio.getTime())) return null;
  return new Date(inicio.getTime() + duracionTratamiento(row.tratamiento) * 60 * 1000);
};

const ahora = new Date();

return $input.all()
  .map(item => item.json || {})
  .filter(row => {
    const estado = (row.estado || '').toLowerCase().trim();
    const solicitada = (row.valoracion_solicitada || '').toLowerCase().trim();
    const telefono = (row['Numero de telefono'] || row.telefono || row.phone || '').toString().trim();
    const eventId = row['Event ID'];
    const fin = finCita(row);
    if (!fin) return false;
    const disponibleParaPedir = ahora.getTime() >= fin.getTime() + ESPERA_POST_CITA_MIN * 60 * 1000;
    return estado === 'confirmada' && solicitada === 'no' && telefono !== '' && !!eventId && disponibleParaPedir;
  })
  .map(row => ({
    json: {
      ...row,
      eventId: row['Event ID'],
      telefono: (row['Numero de telefono'] || row.telefono || row.phone || '').toString(),
      respuesta: 'Hola ' + (row.nombre || '') + ', esperamos que tu visita haya ido muy bien. Podrias valorar tu experiencia del 1 al 5 estrellas? Si quieres, puedes anadir un comentario. Ej: 5 Todo genial'
    }
  }));
